<script lang="ts">
import {translatedName} from './localization';

 import {languageOverrides} from "./localization";
 import {Search,X} from '@lucide/svelte';import {translator} from './i18n';
 import AccountList from "./AccountList.svelte";
 import RecordToolbar from './RecordToolbar.svelte';import type {Project} from './model';
 import type {ReportLookupRequest} from './report-settings';
 export let project:Project;export let onmanage:(action:'add'|'copy'|'edit'|'mark',kind:NonNullable<ReportLookupRequest['kind']>,id?:string)=>void;export let request:ReportLookupRequest;export let language:'ru'|'ro'|"en";export let onclose:()=>void;
 let query='',selected=[...request.selected],current=request.selected[0]||'';$:t=translator(language,$languageOverrides);
 $:liveItems=request.kind==='accounts'?project.accounts.map(a=>({id:a.id,code:a.number,name:a.payer_name,address:a.address})):request.kind==='services'?project.services.map((s,i)=>({id:s.id,code:String(s.report_order??i+1),name:translatedName(s.name,language,$languageOverrides)})):request.kind?(project.reference_catalogs[request.kind]||[]).map(r=>({id:r.id,code:r.code,name:r.name})):request.items;
 $:matches=liveItems.filter(r=>(r.code+' '+r.name+' '+('address' in r?r.address||'':'')).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 function choose(id:string){selected=request.multiple?(selected.includes(id)?selected.filter(v=>v!==id):[...selected,id]):[id];request.onchoose(selected);if(!request.multiple)onclose();}
</script>
{#if request.kind==='accounts'}<AccountList {project} parentId={'reportlookup:'+request.id} multiple={request.multiple} selectedIds={selected} onchoose={choose} onadd={()=>onmanage('add','accounts')} oncopy={a=>onmanage('copy','accounts',a.id)} onedit={a=>onmanage('edit','accounts',a.id)} onmark={a=>onmanage('mark','accounts',a.id)}/>{:else}
<div class="lookup-content"><RecordToolbar {language} selected={!!current} onadd={request.kind?()=>onmanage('add',request.kind!):undefined} oncopy={request.kind?()=>onmanage('copy',request.kind!,current):undefined} onedit={request.kind?()=>onmanage('edit',request.kind!,current):undefined} onremove={request.kind?()=>onmanage('mark',request.kind!,current):undefined} onrefresh={()=>query=''} onfilter={()=>{const input=document.querySelector<HTMLInputElement>('[data-lookup-search="'+request.id+'"]');input?.focus();}} onclearfilter={()=>query=''} filterActive={!!query}/>
<div class="lookup-tools"><label><Search size={17}/><input data-lookup-search={request.id} aria-label={t('Поиск','Căutare')} bind:value={query}/></label><button class="button secondary" onclick={()=>query=''}><X size={16}/>{t('Снять отбор','Resetează filtrul')}</button></div><div class="table-wrap"><table><thead><tr>{#if request.multiple}<th></th>{/if}<th>{t('Код / номер','Cod / număr')}</th><th>{t('Наименование','Denumire')}</th>{#if liveItems.some(r=>'address' in r&&r.address)}<th>{t('Объект учёта / адрес','Obiect / adresă')}</th>{/if}</tr></thead><tbody>{#each matches as row}<tr class:selected={current===row.id||selected.includes(row.id)} onclick={()=>current=row.id} ondblclick={()=>choose(row.id)}>{#if request.multiple}<td><input type="checkbox" aria-label={row.name} checked={selected.includes(row.id)} onchange={()=>choose(row.id)}/></td>{/if}<td>{row.code}</td><td>{row.name}</td>{#if liveItems.some(r=>'address' in r&&r.address)}<td>{'address' in row?row.address||'':''}</td>{/if}</tr>{/each}</tbody></table></div>{#if !matches.length}<p>{t('Записей не найдено.','Nu s-au găsit înregistrări.')}</p>{/if}</div>{/if}
<style>.lookup-content{padding:12px;display:flex;flex-direction:column;gap:10px;min-height:100%;box-sizing:border-box}.lookup-tools{display:flex;gap:12px}.lookup-tools label{display:flex;align-items:center;gap:8px;flex:1}.lookup-tools input{width:100%}table{width:100%;border-collapse:collapse}th{text-align:left;background:#80808020;font-weight:700;padding:8px}td{padding:8px;border-bottom:1px solid var(--border)}.selected{background:#489bcb30}tbody tr:hover{background:#80808020}</style>
